from __future__ import annotations

import ipaddress
import re
from pathlib import PurePosixPath
from typing import Literal
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from .saved_views import SavedViewCreate, SavedViewDelete, SavedViewUpdate


class Input(BaseModel):
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)


def relative_path(value: str) -> str:
    path = PurePosixPath(value)
    if any(ord(char) < 32 for char in value) or "\\" in value or "\x00" in value or path.is_absolute() or ".." in path.parts:
        raise ValueError("Use a relative path inside the workspace")
    return value


class ProjectCreate(Input):
    name: str = Field(min_length=1, max_length=100)
    goal: str = Field(default="", max_length=4000)
    directory: str = Field(default=".", max_length=400)
    notes: str = Field(default="", max_length=16000)

    @field_validator("directory")
    @classmethod
    def directory_path(cls, value: str) -> str:
        return relative_path(value)


class ModelCreate(Input):
    kind: str = Field(default="chat_completions", pattern="^(chat_completions|codex_cli)$")
    name: str = Field(min_length=1, max_length=80)
    endpoint: str = Field(min_length=5, max_length=500)
    model: str = Field(min_length=1, max_length=150)
    key_env: str = Field(default="", max_length=100)

    @field_validator("endpoint")
    @classmethod
    def endpoint_url(cls, value: str) -> str:
        url = urlsplit(value)
        if value == "codex://local":
            return value
        if not url.hostname or url.username or url.password or url.query or url.fragment:
            raise ValueError("Endpoint must not contain credentials, query or fragment")
        if url.port is not None and url.port < 1:
            raise ValueError("Invalid port")
        loopback = url.hostname == "localhost"
        try:
            loopback = loopback or ipaddress.ip_address(url.hostname).is_loopback
        except ValueError:
            pass
        if url.scheme != "https" and not (url.scheme == "http" and loopback):
            raise ValueError("Use HTTPS; HTTP is allowed only for a loopback model server")
        if url.hostname in {"169.254.169.254", "metadata.google.internal"}:
            raise ValueError("Metadata endpoints are not model endpoints")
        return value.rstrip("/")

    @model_validator(mode="after")
    def kind_endpoint_match(self):
        if self.kind == "codex_cli" and self.endpoint != "codex://local":
            raise ValueError("Codex CLI models must use codex://local")
        if self.kind == "chat_completions" and self.endpoint == "codex://local":
            raise ValueError("Chat Completions models must use an HTTP(S) endpoint")
        return self

    @field_validator("key_env")
    @classmethod
    def environment_name(cls, value: str) -> str:
        if value and not re.fullmatch(r"WORKBENCH_MODEL_[A-Z0-9_]+_KEY", value):
            raise ValueError("Use WORKBENCH_MODEL_<NAME>_KEY; the key itself is not accepted")
        return value


class DefaultModel(Input):
    model_id: str = Field(min_length=1, max_length=100)


class ModelTest(Input):
    request_id: str = Field(min_length=8, max_length=100, pattern=r"^[A-Za-z0-9_-]+$")
    consent: bool = False


class BackendCreate(Input):
    name: str = Field(min_length=1, max_length=80)
    kind: str = Field(default="openmausbot", pattern="^openmausbot$")
    endpoint: str = Field(min_length=8, max_length=200)

    @field_validator("endpoint")
    @classmethod
    def loopback_origin(cls, value: str) -> str:
        url = urlsplit(value)
        if (url.scheme not in {"http", "https"} or not url.hostname
                or url.username is not None or url.password is not None
                or url.query or url.fragment or url.path not in {"", "/"}
                or "\\" in value or any(ord(char) < 33 for char in value)):
            raise ValueError("Use a loopback HTTP(S) origin without credentials, path, query or fragment")
        try:
            if not ipaddress.ip_address(url.hostname).is_loopback:
                raise ValueError
            if url.port is not None and url.port < 1:
                raise ValueError
        except ValueError:
            raise ValueError("Only literal loopback IP addresses are supported") from None
        return value.rstrip("/")


class BackendCheck(Input):
    consent: bool = False


class TaskCreate(Input):
    project_id: str
    title: str = Field(min_length=1, max_length=160)
    goal: str = Field(min_length=8, max_length=8000)
    acceptance: str = Field(default="", max_length=4000)
    files: list[str] = Field(default_factory=list, max_length=10)

    @field_validator("files")
    @classmethod
    def file_paths(cls, values: list[str]) -> list[str]:
        return list(dict.fromkeys(relative_path(value) for value in values if value))


class RunCreate(Input):
    coordinator_model: str
    researcher_model: str
    reviewer_model: str
    max_calls: int = Field(default=4, ge=3, le=8)
    parallel: int = Field(default=2, ge=1, le=2)
    minutes: int = Field(default=10, ge=1, le=30)
    max_output_tokens: int = Field(default=1800, ge=256, le=4096)
    consent: bool = False
    request_id: str = Field(min_length=8, max_length=100)
    context_hash: str = Field(pattern="^[0-9a-f]{64}$")
    workflow_version: int | None = Field(default=None, ge=1, le=9007199254740991, strict=True)


class Resume(Input):
    acknowledge_replay: bool = False


class RunRetry(Input):
    coordinator_model: str
    researcher_model: str
    reviewer_model: str
    max_calls: int = Field(default=4, ge=1, le=8)
    parallel: int = Field(default=1, ge=1, le=2)
    minutes: int = Field(default=10, ge=1, le=30)
    max_output_tokens: int = Field(default=1800, ge=256, le=4096)
    call_timeout_seconds: int = Field(default=120, ge=10, le=300)
    consent: bool = False
    acknowledge_replay: bool = False
    request_id: str = Field(min_length=8, max_length=100)
    snapshot_hash: str = Field(pattern="^[0-9a-f]{64}$")


class RecoveryIntentConfig(Input):
    coordinator_model: str = Field(min_length=1, max_length=100)
    researcher_model: str = Field(min_length=1, max_length=100)
    reviewer_model: str = Field(min_length=1, max_length=100)
    max_calls: int = Field(ge=1, le=8)
    parallel: int = Field(ge=1, le=2)
    minutes: int = Field(ge=1, le=30)
    max_output_tokens: int = Field(ge=256, le=4096)
    call_timeout_seconds: int = Field(ge=10, le=300)


class RecoveryIntentCreate(Input):
    request_id: str = Field(min_length=8, max_length=100, pattern=r"^[A-Za-z0-9_-]+$")
    mode: Literal["retry", "resume"]
    snapshot_hash: str = Field(pattern="^[0-9a-f]{64}$")
    config: RecoveryIntentConfig | None = None

    @model_validator(mode="after")
    def resources_match_operation(self):
        if self.mode == "retry" and self.config is None:
            raise ValueError("recovery_intent_config_required")
        if self.mode == "resume" and self.config is not None:
            raise ValueError("recovery_resume_resources_locked")
        return self


class RecoveryIntentExecute(Input):
    consent: bool = False
    acknowledge_replay: bool = False


class ArtifactDecision(Input):
    decision: str = Field(pattern="^(accepted|changes_requested)$")


class Login(Input):
    token: str = Field(min_length=1, max_length=500)


class PlanItem(Input):
    title: str = Field(min_length=1, max_length=120)
    objective: str = Field(min_length=8, max_length=2000)


class Plan(Input):
    tasks: list[PlanItem] = Field(min_length=1, max_length=2)

"""Private workspace view definitions; no model, filesystem or provider actions."""

from __future__ import annotations

import json
import re
from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator


TaskColumn = Literal[
    "id", "title", "projectName", "status", "updated", "attempts", "created_at",
]
TASK_COLUMNS = ("id", "title", "projectName", "status", "updated", "attempts", "created_at")
QueryState = Literal["pending", "active", "attention", "completed", "other"]
ProjectIdentifier = Annotated[str, Field(min_length=1, max_length=100)]
SAVED_VIEW_ID = re.compile(
    r"(?:[0-9a-fA-F]{32}|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-"
    r"[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})"
)
SORT_QUERIES = {
    "", "ORDER BY CREATED ASC", "ORDER BY CREATED DESC",
    "ORDER BY SUMMARY ASC", "ORDER BY SUMMARY DESC",
}


class SavedViewError(Exception):
    def __init__(self, code: str, status: int, current_revision: int | None = None):
        super().__init__(code)
        self.code = code
        self.status = status
        self.current_revision = current_revision

    def detail(self) -> dict:
        return {
            "code": self.code,
            **({"current_revision": self.current_revision}
               if self.current_revision is not None else {}),
        }


class ViewInput(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)


def unique(values: list, code: str) -> list:
    if len(set(values)) != len(values):
        raise ValueError(code)
    return values


class SavedViewQuery(ViewInput):
    text: str = Field(max_length=2000)
    projects: list[ProjectIdentifier] = Field(max_length=100)
    states: list[QueryState] = Field(max_length=5)
    jql: str = Field(max_length=2000)
    mode: Literal["basic", "jql"]

    @field_validator("projects")
    @classmethod
    def project_values(cls, values: list[str]) -> list[str]:
        if any(value.strip() != value for value in values):
            raise ValueError("saved_view_project_invalid")
        return unique(values, "saved_view_projects_duplicate")

    @field_validator("states")
    @classmethod
    def state_values(cls, values: list[str]) -> list[str]:
        return unique(values, "saved_view_states_duplicate")

    @field_validator("jql")
    @classmethod
    def supported_jql(cls, value: str) -> str:
        normalized = " ".join(value.split()).upper()
        if normalized not in SORT_QUERIES:
            raise ValueError("saved_view_jql_unsupported")
        return normalized


class SavedViewSortRule(ViewInput):
    sortKey: TaskColumn
    direction: Literal["ascending", "descending"]


class SavedViewTable(ViewInput):
    page_size: Literal[20, 50, 100]
    sorts: list[SavedViewSortRule] = Field(max_length=3)
    columns: list[TaskColumn] = Field(min_length=1, max_length=7)
    column_order: list[TaskColumn] = Field(min_length=7, max_length=7)

    @field_validator("page_size", mode="before")
    @classmethod
    def integer_page_size(cls, value):
        if type(value) is not int:
            raise ValueError("saved_view_page_size_invalid")
        return value

    @field_validator("sorts")
    @classmethod
    def unique_sort_keys(cls, values: list[SavedViewSortRule]):
        unique([value.sortKey for value in values], "saved_view_sorts_duplicate")
        return values

    @field_validator("columns")
    @classmethod
    def visible_title(cls, values: list[str]) -> list[str]:
        unique(values, "saved_view_columns_duplicate")
        if "title" not in values:
            raise ValueError("saved_view_title_required")
        return values

    @field_validator("column_order")
    @classmethod
    def complete_order(cls, values: list[str]) -> list[str]:
        if set(values) != set(TASK_COLUMNS):
            raise ValueError("saved_view_column_order_invalid")
        return values


class SavedViewDefinition(ViewInput):
    schema_version: int = Field(ge=1, le=1)
    query: SavedViewQuery
    table: SavedViewTable


class SavedViewNamed(ViewInput):
    name: str = Field(min_length=1, max_length=100)
    definition: SavedViewDefinition

    @field_validator("name", mode="before")
    @classmethod
    def trimmed_name(cls, value):
        return value.strip() if isinstance(value, str) else value


def require_scope(scope_type: str, project_id: str | None, definition: dict) -> None:
    if (
        (scope_type == "workspace" and project_id is not None) or
        (scope_type == "project" and (
            not project_id or definition["query"]["projects"] != [project_id]
        ))
    ):
        raise SavedViewError("saved_view_scope_invalid", 422)


class SavedViewCreate(SavedViewNamed):
    id: str = Field(min_length=32, max_length=36)
    scope_type: Literal["workspace", "project"]
    project_id: ProjectIdentifier | None

    @field_validator("id")
    @classmethod
    def client_identifier(cls, value: str) -> str:
        if not SAVED_VIEW_ID.fullmatch(value):
            raise ValueError("saved_view_id_invalid")
        return value

    @model_validator(mode="after")
    def fixed_scope(self):
        try:
            require_scope(self.scope_type, self.project_id, self.definition.model_dump())
        except SavedViewError as error:
            raise ValueError(error.code) from error
        return self


class SavedViewUpdate(SavedViewNamed):
    expected_revision: int = Field(ge=1)


class SavedViewDelete(ViewInput):
    expected_revision: int = Field(ge=1)


def require_identifier(identifier: str) -> None:
    if not SAVED_VIEW_ID.fullmatch(identifier):
        raise SavedViewError("saved_view_id_invalid", 422)


def public_saved_view(record: dict) -> dict:
    return {
        key: json.loads(record[key]) if key == "definition" else record[key]
        for key in (
            "id", "name", "scope_type", "project_id", "definition",
            "revision", "created_at", "updated_at",
        )
    }


def saved_view_delete_receipt(record: dict) -> dict:
    return {
        "id": record["id"], "deleted": True, "revision": record["revision"],
        "deleted_at": record["deleted_at"],
    }

"""Immutable coding acceptance input, intentionally failing against the baseline."""
import unittest

from workbench.schemas import relative_path


class RelativePathAcceptance(unittest.TestCase):
    def test_rejects_newline(self):
        with self.assertRaises(ValueError):
            relative_path("source\nunexpected.py")

    def test_rejects_tab(self):
        with self.assertRaises(ValueError):
            relative_path("source\tunexpected.py")

    def test_retains_ordinary_source(self):
        self.assertEqual(relative_path("workbench/schemas.py"), "workbench/schemas.py")

    def test_retains_localized_source(self):
        self.assertEqual(relative_path("研发/方案.py"), "研发/方案.py")
